import numpy as np
from scipy.integrate import solve_ivp
import matplotlib.pyplot as plt

zeta = 0.1
# MATLAB: wn   = 2*pi;
wn   = 2 * np.pi
# MATLAB: f    = @(t, y) [y(2); -2*zeta*wn*y(2) - wn^2*y(1)];
f    = lambda t, y: np.array([y[1], -2 * zeta * wn * y[1] - wn**2 * y[0]])
# MATLAB: y0   = [1; 0];
y0   = np.array([1, 0], dtype=float)

# --- fixed-step RK4 -----------------------------------------------------
# MATLAB: h    = 0.01;
h    = 0.01
# MATLAB: t_rk = 0:h:5;
t_rk = np.arange(0, 5 + h/2, h) # MATLAB: 0:h:5 -> np.arange
# MATLAB: n    = numel(t_rk);
n    = np.size(t_rk) # MATLAB: numel -> np.size / .size
# MATLAB: Y    = zeros(2, n);
Y    = np.zeros((2, n)) # MATLAB: zeros -> np.zeros
# MATLAB: Y(:, 1) = y0;
Y[:, 0] = y0
# MATLAB: for k = 1:n-1
for k in range(0, n - 1):
    tk = t_rk[k]
    yk = Y[:, k]
    k1 = f(tk,       yk)
    k2 = f(tk + h/2, yk + h/2*k1)
    k3 = f(tk + h/2, yk + h/2*k2)
    k4 = f(tk + h,   yk + h*k3)
    # MATLAB: Y(:, k+1) = yk + h/6*(k1 + 2*k2 + 2*k3 + k4);
    Y[:, k+1] = yk + h/6*(k1 + 2*k2 + 2*k3 + k4)
# MATLAB: x_rk4   = Y(1, :);
x_rk4   = Y[0, :]
# MATLAB: rk4_end = Y(:, end)';
rk4_end = Y[:, -1] # MATLAB: Y(:, end)' -> Y[:, -1]
# MATLAB: energy  = 0.5*Y(2, :).^2 + 0.5*wn^2*Y(1, :).^2;
energy  = 0.5 * Y[1, :]**2 + 0.5 * wn**2 * Y[0, :]**2

# --- adaptive ode45 with tight tolerances -------------------------------
# MATLAB: opts = odeset('RelTol', 1e-10, 'AbsTol', 1e-12);
# MATLAB: [t45, y45] = ode45(f, [0 5], y0, opts);
sol = solve_ivp(f, [0, 5], y0, method='RK45', rtol=1e-10, atol=1e-12) # MATLAB: ode45 -> scipy.integrate.solve_ivp(method='RK45')
t45 = sol.t
y45 = sol.y.T
# MATLAB: y45_end = y45(end, :);
y45_end = y45[-1, :]

# --- exact solution for comparison --------------------------------------
# MATLAB: wd      = wn*sqrt(1 - zeta^2);
wd      = wn * np.sqrt(1 - zeta**2) # MATLAB: sqrt -> np.sqrt
# MATLAB: x_exact = exp(-zeta*wn*t_rk) .* (cos(wd*t_rk) + zeta*wn/wd*sin(wd*t_rk));
x_exact = np.exp(-zeta * wn * t_rk) * (np.cos(wd * t_rk) + zeta * wn / wd * np.sin(wd * t_rk)) # MATLAB: exp -> np.exp, cos -> np.cos, sin -> np.sin
# MATLAB: rk4_max_error = max(abs(x_rk4 - x_exact));
rk4_max_error = np.max(np.abs(x_rk4 - x_exact)) # MATLAB: max -> np.max / np.argmax, abs -> np.abs
